import{_ as B,H as e,f as t,i as A}from"./chunks/framework.BH2BK_3i.js";const F=JSON.parse('{"title":"特别放送 | 知识回顾（中）","description":"","frontmatter":{},"headers":[],"relativePath":"手把手带你搭建推荐系统/特别放送｜知识回顾（中）.md","filePath":"手把手带你搭建推荐系统/特别放送｜知识回顾（中）.md","lastUpdated":1795557612000}'),s={name:"手把手带你搭建推荐系统/特别放送｜知识回顾（中）.md"};function i(n,E,a,p,o,r){return e(),t("div",null,[...E[0]||(E[0]=[A('<h1 id="特别放送-知识回顾-中" tabindex="-1">特别放送 | 知识回顾（中） <a class="header-anchor" href="#特别放送-知识回顾-中" aria-label="Permalink to &quot;特别放送 | 知识回顾（中）&quot;">​</a></h1><p>你好，我是黄鸿波。</p><p>今天我们继续来进行知识回顾，这节课我们将聚焦在召回篇：基于规则的召回以及服务搭建篇，话不多说，直接开始今天的复习课。</p><p>11｜基于规则的召回：如何使用规则找到用户的兴趣点？</p><p>本节课的重点在于了解召回对于推荐系统的意义，并熟悉基于规则的召回种类到底有哪些。其中，基于时间召回是最简单的一种召回算法，主要依照内容产生时间的顺序进行召回，一般需要配合其他召回方式一起使用。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E5%B8%A6%E4%BD%A0%E6%90%AD%E5%BB%BA%E6%8E%A8%E8%8D%90%E7%B3%BB%E7%BB%9F/images/%25E7%2589%25B9%25E5%2588%25AB%25E6%2594%25BE%25E9%2580%2581-%25E7%259F%25A5%25E8%25AF%2586%25E5%259B%259E%25E9%25A1%25BE%25EF%25BC%2588%25E4%25B8%25AD%25EF%25BC%2589/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E5%B8%A6%E4%BD%A0%E6%90%AD%E5%BB%BA%E6%8E%A8%E8%8D%90%E7%B3%BB%E7%BB%9F/images/%25E7%2589%25B9%25E5%2588%25AB%25E6%2594%25BE%25E9%2580%2581-%25E7%259F%25A5%25E8%25AF%2586%25E5%259B%259E%25E9%25A1%25BE%25EF%25BC%2588%25E4%25B8%25AD%25EF%25BC%2589/1.png" alt=""></a></p><p>12｜基于热度的召回：如何使用热门内容来吸引用户？</p><p>本节课的重点在于学习基于热度召回的热度值是怎么算出来的，并且熟悉怎么做热度值的变化更新，这就要求我们对牛顿冷却定律有一定的了解。最后我还带你整体过了一遍基于热度召回的实现思路。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E5%B8%A6%E4%BD%A0%E6%90%AD%E5%BB%BA%E6%8E%A8%E8%8D%90%E7%B3%BB%E7%BB%9F/images/%25E7%2589%25B9%25E5%2588%25AB%25E6%2594%25BE%25E9%2580%2581-%25E7%259F%25A5%25E8%25AF%2586%25E5%259B%259E%25E9%25A1%25BE%25EF%25BC%2588%25E4%25B8%25AD%25EF%25BC%2589/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E5%B8%A6%E4%BD%A0%E6%90%AD%E5%BB%BA%E6%8E%A8%E8%8D%90%E7%B3%BB%E7%BB%9F/images/%25E7%2589%25B9%25E5%2588%25AB%25E6%2594%25BE%25E9%2580%2581-%25E7%259F%25A5%25E8%25AF%2586%25E5%259B%259E%25E9%25A1%25BE%25EF%25BC%2588%25E4%25B8%25AD%25EF%25BC%2589/2.png" alt=""></a></p><p>13｜基于关键词的召回：如何使用关键词吸引用户？</p><p>本节课的重点在于学习基于关键词的召回算法的实现过程，同时我们讲解了提取关键词中两种常见的算法：TF-IDF 和 TextRank 算法，以及这两种算法的实现原理，这个也需要重点掌握。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E5%B8%A6%E4%BD%A0%E6%90%AD%E5%BB%BA%E6%8E%A8%E8%8D%90%E7%B3%BB%E7%BB%9F/images/%25E7%2589%25B9%25E5%2588%25AB%25E6%2594%25BE%25E9%2580%2581-%25E7%259F%25A5%25E8%25AF%2586%25E5%259B%259E%25E9%25A1%25BE%25EF%25BC%2588%25E4%25B8%25AD%25EF%25BC%2589/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E5%B8%A6%E4%BD%A0%E6%90%AD%E5%BB%BA%E6%8E%A8%E8%8D%90%E7%B3%BB%E7%BB%9F/images/%25E7%2589%25B9%25E5%2588%25AB%25E6%2594%25BE%25E9%2580%2581-%25E7%259F%25A5%25E8%25AF%2586%25E5%259B%259E%25E9%25A1%25BE%25EF%25BC%2588%25E4%25B8%25AD%25EF%25BC%2589/3.png" alt=""></a></p><p>14｜基于 Flask 的推荐服务：搭建基础的 Flask 服务</p><p>本节课我们在 Python 环境下使用 Flask 框架，搭建了一个简单的接口，并使用 Postman 来进行调用，最后得到了一个正确的输出。要想搭建一个推荐系统服务，你至少需要对 Web 服务、接口、模型的调用、数据的流转有着整体的认识。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E5%B8%A6%E4%BD%A0%E6%90%AD%E5%BB%BA%E6%8E%A8%E8%8D%90%E7%B3%BB%E7%BB%9F/images/%25E7%2589%25B9%25E5%2588%25AB%25E6%2594%25BE%25E9%2580%2581-%25E7%259F%25A5%25E8%25AF%2586%25E5%259B%259E%25E9%25A1%25BE%25EF%25BC%2588%25E4%25B8%25AD%25EF%25BC%2589/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E5%B8%A6%E4%BD%A0%E6%90%AD%E5%BB%BA%E6%8E%A8%E8%8D%90%E7%B3%BB%E7%BB%9F/images/%25E7%2589%25B9%25E5%2588%25AB%25E6%2594%25BE%25E9%2580%2581-%25E7%259F%25A5%25E8%25AF%2586%25E5%259B%259E%25E9%25A1%25BE%25EF%25BC%2588%25E4%25B8%25AD%25EF%25BC%2589/4.png" alt=""></a></p><p>15｜基于 Flask 的推荐服务：如何把召回集推荐出去？</p><p>本节课的重点在于编写基于时间的召回并将基于时间的召回推荐给用户。在这个过程你要特别注意“时间穿越”的问题，同时，我们可以使用翻页请求的方式来提高用户体验。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E5%B8%A6%E4%BD%A0%E6%90%AD%E5%BB%BA%E6%8E%A8%E8%8D%90%E7%B3%BB%E7%BB%9F/images/%25E7%2589%25B9%25E5%2588%25AB%25E6%2594%25BE%25E9%2580%2581-%25E7%259F%25A5%25E8%25AF%2586%25E5%259B%259E%25E9%25A1%25BE%25EF%25BC%2588%25E4%25B8%25AD%25EF%25BC%2589/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E5%B8%A6%E4%BD%A0%E6%90%AD%E5%BB%BA%E6%8E%A8%E8%8D%90%E7%B3%BB%E7%BB%9F/images/%25E7%2589%25B9%25E5%2588%25AB%25E6%2594%25BE%25E9%2580%2581-%25E7%259F%25A5%25E8%25AF%2586%25E5%259B%259E%25E9%25A1%25BE%25EF%25BC%2588%25E4%25B8%25AD%25EF%25BC%2589/5.png" alt=""></a></p><p>16｜基础用户画像：如何用好用户的注册信息？</p><p>本节课的重点在于熟悉如何使用 Python 搭建一个 Webservice 服务，通过注册的方式收集最基础的用户画像，以及知道如何安装 MySQL 数据库、如何利用 Python 来操作它。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E5%B8%A6%E4%BD%A0%E6%90%AD%E5%BB%BA%E6%8E%A8%E8%8D%90%E7%B3%BB%E7%BB%9F/images/%25E7%2589%25B9%25E5%2588%25AB%25E6%2594%25BE%25E9%2580%2581-%25E7%259F%25A5%25E8%25AF%2586%25E5%259B%259E%25E9%25A1%25BE%25EF%25BC%2588%25E4%25B8%25AD%25EF%25BC%2589/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E5%B8%A6%E4%BD%A0%E6%90%AD%E5%BB%BA%E6%8E%A8%E8%8D%90%E7%B3%BB%E7%BB%9F/images/%25E7%2589%25B9%25E5%2588%25AB%25E6%2594%25BE%25E9%2580%2581-%25E7%259F%25A5%25E8%25AF%2586%25E5%259B%259E%25E9%25A1%25BE%25EF%25BC%2588%25E4%25B8%25AD%25EF%25BC%2589/6.png" alt=""></a></p><p>17｜推荐系统前端：如何用一个界面展示我们的成果？</p><p>本节课的重点在于学习在服务端代码中增加点赞、收藏等交互信息，以及如何使用 Vue.js 对接我们的 HTTP 服务进行展示。Vue.js 是一个构建用户界面的渐进式框架，核心库只关注视图层。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E5%B8%A6%E4%BD%A0%E6%90%AD%E5%BB%BA%E6%8E%A8%E8%8D%90%E7%B3%BB%E7%BB%9F/images/%25E7%2589%25B9%25E5%2588%25AB%25E6%2594%25BE%25E9%2580%2581-%25E7%259F%25A5%25E8%25AF%2586%25E5%259B%259E%25E9%25A1%25BE%25EF%25BC%2588%25E4%25B8%25AD%25EF%25BC%2589/7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E5%B8%A6%E4%BD%A0%E6%90%AD%E5%BB%BA%E6%8E%A8%E8%8D%90%E7%B3%BB%E7%BB%9F/images/%25E7%2589%25B9%25E5%2588%25AB%25E6%2594%25BE%25E9%2580%2581-%25E7%259F%25A5%25E8%25AF%2586%25E5%259B%259E%25E9%25A1%25BE%25EF%25BC%2588%25E4%25B8%25AD%25EF%25BC%2589/7.png" alt=""></a></p><p>18｜一个简单的推荐服务闭环包括哪些模块？</p><p>这节课实际上是对前面的课程做一个比较系统的总结，也对后面的课程做一个铺垫。我们整体过了一遍一个简单的推荐服务闭环包括哪些模块，了解了各个部分如何流转。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E5%B8%A6%E4%BD%A0%E6%90%AD%E5%BB%BA%E6%8E%A8%E8%8D%90%E7%B3%BB%E7%BB%9F/images/%25E7%2589%25B9%25E5%2588%25AB%25E6%2594%25BE%25E9%2580%2581-%25E7%259F%25A5%25E8%25AF%2586%25E5%259B%259E%25E9%25A1%25BE%25EF%25BC%2588%25E4%25B8%25AD%25EF%25BC%2589/8.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E5%B8%A6%E4%BD%A0%E6%90%AD%E5%BB%BA%E6%8E%A8%E8%8D%90%E7%B3%BB%E7%BB%9F/images/%25E7%2589%25B9%25E5%2588%25AB%25E6%2594%25BE%25E9%2580%2581-%25E7%259F%25A5%25E8%25AF%2586%25E5%259B%259E%25E9%25A1%25BE%25EF%25BC%2588%25E4%25B8%25AD%25EF%25BC%2589/8.png" alt=""></a></p><p>这次的复习课到这里也就结束了，下节课我将继续带你复习经典召回算法与排序篇的内容，如果你觉得这节课对你有帮助，也欢迎分享给有需要的朋友！</p>',28)])])}const h=B(s,[["render",i]]);export{F as __pageData,h as default};
